INSERT INTO `equipe` VALUES (1,'Administração de Sistemas','Administração e configuração dos sistemas corporativos',1,'2026-01-05 09:00:00'),(2,'Gestão de TI','Gestão de usuários, equipes, incidentes e infraestrutura de TI',1,'2026-01-05 09:00:00'),(3,'Suporte Técnico','Atendimento técnico a estações, notebooks, impressoras e periféricos',1,'2026-01-05 09:00:00'),(4,'Infraestrutura e Servidores','Sustentação de servidores, banco de dados, aplicações e backup',1,'2026-01-05 09:00:00'),(5,'Redes e Segurança','Gestão de firewall, switches, wi-fi e segurança da rede',1,'2026-01-05 09:00:00'),(6,'Service Desk','Atendimento de primeiro nível e abertura de chamados',1,'2026-01-05 09:00:00'),(7,'Recursos Humanos','Gestão de pessoas e informações de colaboradores',1,'2026-01-05 09:00:00'),(8,'Financeiro','Rotinas administrativas e financeiras',1,'2026-01-05 09:00:00'),(9,'Comercial','Vendas e relacionamento com clientes',1,'2026-01-05 09:00:00'),(10,'Operações','Gestão operacional e acompanhamento das áreas',1,'2026-01-05 09:00:00'),(11,'Auditoria e Compliance','Auditoria de registros e conformidade',1,'2026-01-05 09:00:00'),(12,'Diretoria','Direção e acompanhamento gerencial',1,'2026-01-05 09:00:00'),(13,'Administrativo','Rotinas administrativas gerais',1,'2026-01-05 09:00:00'),(500,'NOC 25','Equipe responsável pela operação e acompanhamento contínuo da infraestrutura e dos serviços de TI. Equipe 25 destinada à gestão e ao tratamento de incidentes de TI.',1,'2025-05-21 11:30:00');
