DROP TABLE IF EXISTS `historico_incidente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `historico_incidente` (
  `id_historico_incidente` bigint(150) NOT NULL,
  `campo_alterado` varchar(100) NOT NULL,
  `valor_anterior` text DEFAULT NULL,
  `valor_novo` text DEFAULT NULL,
  `data_alteracao` datetime NOT NULL,
  `observacao` varchar(500) DEFAULT NULL,
  `id_incidente` bigint(150) NOT NULL,
  `id_usuario` bigint(100) NOT NULL,
  PRIMARY KEY (`id_historico_incidente`),
  KEY `fk_HISTORICO_INCIDENTE_INCIDENTE1_idx` (`id_incidente`),
  KEY `fk_HISTORICO_INCIDENTE_USUARIO1_idx` (`id_usuario`),
  CONSTRAINT `fk_HISTORICO_INCIDENTE_INCIDENTE1` FOREIGN KEY (`id_incidente`) REFERENCES `incidente` (`id_incidente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_HISTORICO_INCIDENTE_USUARIO1` FOREIGN KEY (`id_usuario`) REFERENCES `usuario` (`id_usuario`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
