--
-- Table structure for table `incidente`
--

DROP TABLE IF EXISTS `incidente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `incidente` (
  `id_incidente` bigint(150) NOT NULL,
  `codigo` varchar(35) NOT NULL,
  `titulo` varchar(200) NOT NULL,
  `descricao` text NOT NULL,
  `data_ocorrencia` datetime NOT NULL,
  `data_registro` datetime NOT NULL,
  `id_origem_incidente` int(11) NOT NULL,
  `id_categoria_incidente` int(11) NOT NULL,
  `id_severidade` tinyint(100) NOT NULL,
  `id_status_incidente` tinyint(150) NOT NULL,
  `id_ativo` bigint(100) NOT NULL,
  `id_usuario` bigint(100) NOT NULL,
  `data_atualizacao` datetime NOT NULL,
  `data_resolucao` datetime DEFAULT NULL,
  `data_encerramento` datetime DEFAULT NULL,
  PRIMARY KEY (`id_incidente`),
  UNIQUE KEY `codigo_UNIQUE` (`codigo`),
  KEY `fk_INCIDENTE_ORIGEM_INCIDENTE1_idx` (`id_origem_incidente`),
  KEY `fk_INCIDENTE_CATEGORIA_INCIDENTE1_idx` (`id_categoria_incidente`),
  KEY `fk_INCIDENTE_SEVERIDADE1_idx` (`id_severidade`),
  KEY `fk_INCIDENTE_STATUS_INCIDENTE1_idx` (`id_status_incidente`),
  KEY `fk_INCIDENTE_ATIVO1_idx` (`id_ativo`),
  KEY `fk_INCIDENTE_USUARIO1_idx` (`id_usuario`),
  CONSTRAINT `fk_INCIDENTE_ATIVO1` FOREIGN KEY (`id_ativo`) REFERENCES `ativo` (`id_ativo`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_INCIDENTE_CATEGORIA_INCIDENTE1` FOREIGN KEY (`id_categoria_incidente`) REFERENCES `categoria_incidente` (`id_categoria_incidente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_INCIDENTE_ORIGEM_INCIDENTE1` FOREIGN KEY (`id_origem_incidente`) REFERENCES `origem_incidente` (`id_origem_incidente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_INCIDENTE_SEVERIDADE1` FOREIGN KEY (`id_severidade`) REFERENCES `severidade` (`id_severidade`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_INCIDENTE_STATUS_INCIDENTE1` FOREIGN KEY (`id_status_incidente`) REFERENCES `status_incidente` (`id_status_incidente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_INCIDENTE_USUARIO1` FOREIGN KEY (`id_usuario`) REFERENCES `usuario` (`id_usuario`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

